DROP TABLE IF EXISTS `jobs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `jobs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `job_source` varchar(50) NOT NULL,
  `source_job_id` varchar(100) NOT NULL,
  `title` varchar(255) DEFAULT NULL,
  `company` varchar(255) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `country` varchar(50) DEFAULT NULL,
  `is_remote` tinyint(1) DEFAULT NULL,
  `apply_link` text,
  `description` longtext,
  `salary_text` varchar(255) DEFAULT NULL,
  `salary_min` decimal(12,2) DEFAULT NULL,
  `salary_max` decimal(12,2) DEFAULT NULL,
  `salary_currency` varchar(10) DEFAULT NULL,
  `salary_period` varchar(20) DEFAULT NULL,
  `salary_source` varchar(50) DEFAULT NULL,
  `keywords` text,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_source_job` (`job_source`,`source_job_id`),
  UNIQUE KEY `uq_jobs_source` (`job_source`,`source_job_id`)
) ENGINE=InnoDB AUTO_INCREMENT=459 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
